def free_slots(limit, busy):
    if limit <= 0:
        return []

    busy_intervals = sorted(busy)
    free_intervals = []

    for start, end in busy_intervals:
        if not free_intervals or start > free_intervals[-1][1]:
            free_intervals.append([start, end])
        else:
            free_intervals[-1][1] = max(free_intervals[-1][1], end)

    return [interval for interval in free_intervals if interval[0] <= limit]

from typing import List

def shortest_span(values: List[int], threshold: int) -> int:
    if not values:
        return 0

    left, right = 0, 0
    current_sum = values[left]
    min_span = float('inf')

    while right < len(values):
        if current_sum >= threshold:
            min_span = min(min_span, right - left + 1)
            current_sum -= values[left]
            left += 1
        else:
            right += 1
            if right < len(values):
                current_sum += values[right]

    return min_span if min_span != float('inf') else 0

from collections import defaultdict

def build_layers(n, prerequisites):
    graph = defaultdict(list)
    indegree = [0] * n

    for a, b in prerequisites:
        graph[a].append(b)
        indegree[b] += 1

    queue = [i for i in range(n) if indegree[i] == 0]
    layers = []

    while queue:
        layer = []
        for _ in range(len(queue)):
            node = queue.pop(0)
            layer.append(node)
            for neighbor in graph[node]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)
        layers.append(layer)

    if len(layers[-1]) != n:
        return []

    return layers

def top_words(words, k):
    if k <= 0:
        return []

    word_counts = {}
    for word in words:
        word_counts[word] = word_counts.get(word, 0) + 1

    sorted_words = sorted(word_counts.items(), key=lambda x: (-x[1], x[0]))

    return [word for word, count in sorted_words[:k]]

