import sys

def main():
    inventory = {}
    while True:
        command = sys.stdin.readline().strip()
        if not command:
            break
        parts = command.split()
        if parts[0] == "PUT":
            name = parts[1]
            if name not in inventory:
                inventory[name] = 0
            inventory[name] += 1
        elif parts[0] == "TAKE":
            name = parts[1]
            if name in inventory and inventory[name] > 0:
                inventory[name] -= 1
        elif parts[0] == "QUERY":
            name = parts[1]
            if name in inventory:
                print(inventory[name], end="")
            else:
                print("0", end="")
        print()

if __name__ == "__main__":
    main()
